SourceCode.Declaration:
/// <summary>
/// The result of a claim attempt. Always tells the caller who holds the line now, whether or
/// not that turned out to be them - "someone else has it" is a normal answer here, not a
/// failure, and is reported as [granted] = false with [claimedByUserName]/[claimedByDisplayName]
/// filled in from whoever actually holds it.
/// </summary>
[DataContractAttribute]
class HSMobileOpsClaimResponse
{
    boolean success;
    str     errorCode;
    str     message;

    boolean granted;
    str     claimedByUserName;
    str     claimedByDisplayName;
    utcdatetime claimExpiresUtc;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

/// <summary>
/// True when the caller now holds the claim - a fresh claim or a renewal of their own. False
/// means someone else's live claim blocked it; [claimedByUserName] says who.
/// </summary>
[DataMemberAttribute('Granted')]
public boolean parmGranted(boolean _value = granted)
{
    granted = _value;
    return granted;
}

[DataMemberAttribute('ClaimedByUserName')]
public str parmClaimedByUserName(str _value = claimedByUserName)
{
    claimedByUserName = _value;
    return claimedByUserName;
}

[DataMemberAttribute('ClaimedByDisplayName')]
public str parmClaimedByDisplayName(str _value = claimedByDisplayName)
{
    claimedByDisplayName = _value;
    return claimedByDisplayName;
}

[DataMemberAttribute('ClaimExpiresUtc')]
public utcdatetime parmClaimExpiresUtc(utcdatetime _value = claimExpiresUtc)
{
    claimExpiresUtc = _value;
    return claimExpiresUtc;
}
